<?php
require_once __DIR__ . '/Model.php';
class UserModel extends Model { protected $table = 'users'; public function by_username($username) { $st = db()->prepare('SELECT * FROM users WHERE username = ? LIMIT 1'); $st->execute([$username]); return $st->fetch(); } public function change_password($uid, $hash) { db()->prepare('UPDATE users SET password_hash = ? WHERE id = ?')->execute([$hash, (int)$uid]); } public function update_profile($uid, $data) { $sets = []; foreach ($data as $k => $v) $sets[] = "$k = :$k"; $data['id'] = (int)$uid; db()->prepare('UPDATE users SET ' . implode(', ', $sets) . ' WHERE id = :id')->execute($data); } public function get_advised_courses($uid) { $st = db()->prepare('SELECT c.* FROM courses c INNER JOIN course_advisors ca ON ca.course_id = c.id WHERE ca.user_id = ?'); $st->execute([(int)$uid]); return $st->fetchAll(); } public function get_taught_courses($uid) { $st = db()->prepare('SELECT DISTINCT c.* FROM courses c INNER JOIN schedules s ON s.course_id = c.id WHERE s.teacher_user_id = ?'); $st->execute([(int)$uid]); return $st->fetchAll(); } }
